class Solution {
public:
    vector<int> luckyNumbers(vector<vector<int>>& matrix) {
        int m = matrix.size();
        int n = matrix[0].size();

        int r = INT_MIN;
        for (int i = 0; i < m; i++) {
            int rowMin = matrix[i][0];
            for (int j = 1; j < n; j++) {
                if (matrix[i][j] < rowMin) rowMin = matrix[i][j];
            }
            if (rowMin > r) r = rowMin;
        }

        int c = INT_MAX;
        for (int j = 0; j < n; j++) {
            int colMax = matrix[0][j];
            for (int i = 1; i < m; i++) {
                if (matrix[i][j] > colMax) colMax = matrix[i][j];
            }
            if (colMax < c) c = colMax;
        }

        if (r == c) return {r};
        return {};
    }
};
